// Item 22b.5 M3b-ii: the pinned pseudo-additive decomposition mode, verified
// end to end against the pinned rjd3 3.9.0 jars. Every embedded value comes
// verbatim (17 significant digits) from validation/evidence/native/
// x11-{bpass,cpass,dpass,selection}-padd, captured by
// validation/reference/capture-x11-{bpass,cpass,dpass,selection}.R
// --mode=PseudoAdditive from the pinned pseudoadd.X11BStepPseudoAdd/
// X11CStepPseudoAdd/X11DStepPseudoAdd classes and the X11Kernel's own
// pseudo-additive selection flow. PseudoAdditive is multiplicative in the
// pinned truth table isMultiplicative() == (mode == Multiplicative || mode ==
// PseudoAdditive): the whole context runs the RATIO arithmetic (ctx.remove,
// the sigma/correction arithmetic with the mode default 1, the mode-aware
// calcICR) and the makePositivity trend guards engage (fixture repair
// columns: B7 on the spikeend and wideband cases, C7 and D7/D12 on the
// wideband cases), while the X11{B,C,D}StepPseudoAdd subclasses override
// exactly the composition sites whose forms decode through PseudoAddUtility
// (bytecode-exact: removeSeasonalAdjusted(a, b, c) is a - c*(b - 1),
// adjustRefSeries(a, b, c, d) is a + c*(d/b - d), removeIrregular(a, b) is
// a - b + 1, removeSeasonalAdjustedWithBorders keeps the ratio x/s at the
// borders and x - f*(s - 1) inside): b4d, b6, b9d, b11, c1, c6, c11, d1, d6,
// d8, d11, d11bis and the global-MSR walk (MsrFilterSelectionPseudoAdd:
// irregular x - seas + 1, the MsrTable.of relative flag staying the strict
// mode == Multiplicative test). Unlike Multiplicative and LogAdditive the
// pinned check() imposes NO positivity requirement on PseudoAdditive, so
// non-positive inputs are legal and never reach a positivity message. The
// b_pinned/c_pinned/d_pinned subsets are the quarterly inventory (masked
// case, both repair categories, two extended calendars) and the selection
// subset is the complete 15-case pinned kernel inventory in pseudo-additive
// mode; the monthly inventory is re-verified by the tools/verify_x11_*pass
// sweeps over the full fixtures. In the pseudo domain the constant-msr
// contrast is decided (I/C ratio 3.515625 like the multiplicative run) while
// const-fixed stays NaN-degenerate. Contract:
// docs/contracts/x11-pseudo-additive-contract.md.
